+import * as YAML from "yaml";
+
+const sanitizeRuleName = (n) => n.toLowerCase().replace(/[^a-z0-9\s-]/g,"").replace(/\s+/g,"-").replace(/^-+|-+$/g,"");
+console.log("sanitize tests:");
+console.log(JSON.stringify(sanitizeRuleName("Special Ch@racters & Spaces")), "=> special-chracters-spaces");
+console.log(JSON.stringify(sanitizeRuleName("   ")), "=> ''");
+console.log(JSON.stringify(sanitizeRuleName("")), "=> ''");
+console.log(JSON.stringify(sanitizeRuleName("--Hello--World--")), "=> hello-world");
+
+function createMarkdownWithFrontmatter(fm, md){
+  return `---\n${YAML.stringify(fm).trim()}\n---\n\n${md}`;
+}
+const empty = createMarkdownWithFrontmatter({}, "# X\n\nbody");
+console.log("\nempty frontmatter output:\n" + JSON.stringify(empty));
+
+// parse round trip
+function parseMarkdownRule(content){
+  const c = content.replace(/\r\n/g,"\n");
+  const parts = c.split(/^---\s*$/m);
+  if(parts.length>=3){ const fm = YAML.parse(parts[1])||{}; return {frontmatter:fm, markdown: parts.slice(2).join("---").trim()};}
+  return {frontmatter:{}, markdown:c};
+}
+console.log("\nparse empty:", JSON.stringify(parseMarkdownRule(empty)));
+const withFm = createMarkdownWithFrontmatter({description:"d", alwaysApply:false}, "# Y\n\nrule");
+console.log("parse fm:", JSON.stringify(parseMarkdownRule(withFm)));
